function parseDate(value,field){if(typeof value!=='string'||Number.isNaN(Date.parse(value)))throw new TypeError(`${field} date is invalid`);return new Date(value);}
export function validatePlan(tasks){if(!Array.isArray(tasks))throw new TypeError('tasks must be an array');const ids=new Set();const normalized=tasks.map(task=>{if(!task||typeof task!=='object')throw new TypeError('task must be an object');if(typeof task.id!=='string'||task.id.trim()==='')throw new TypeError('task id is required');if(ids.has(task.id))throw new Error(`duplicate task id: ${task.id}`);ids.add(task.id);if(typeof task.title!=='string'||task.title.trim()==='')throw new TypeError('task title is required');const start=parseDate(task.start,'start');const end=parseDate(task.end,'end');if(end<start)throw new RangeError('end date must not precede start date');const dependencies=task.dependencies??[];if(!Array.isArray(dependencies))throw new TypeError('dependencies must be an array');const progress=task.progress??0;if(!Number.isFinite(progress)||progress<0||progress>100)throw new RangeError('progress must be between 0 and 100');return{...task,progress,dependencies:[...dependencies]};});for(const task of normalized){for(const dependency of task.dependencies)if(!ids.has(dependency))throw new Error(`dependency not found: ${dependency}`);}return normalized;}
export function toFrappeGantt(tasks){return validatePlan(tasks).map(task=>({id:task.id,name:task.title,start:task.start,end:task.end,progress:task.progress,dependencies:task.dependencies.join(',')}));}
export function toFullCalendarEvents(tasks){return validatePlan(tasks).map(task=>({id:task.id,title:task.title,start:task.start,end:task.end,allDay:true,extendedProps:{progress:task.progress,resourceId:task.resourceId??null,dependencies:[...task.dependencies]}}));}
export function calculateProgress(tasks){const list=validatePlan(tasks);if(list.length===0)return 0;return list.reduce((total,task)=>total+task.progress,0)/list.length;}
export function findResourceConflicts(tasks){const list=validatePlan(tasks).filter(task=>task.resourceId!=null);const conflicts=[];for(let i=0;i<list.length;i+=1){for(let j=i+1;j<list.length;j+=1){const first=list[i],second=list[j];if(first.resourceId!==second.resourceId)continue;const overlaps=parseDate(first.start,'start')<parseDate(second.end,'end')&&parseDate(second.start,'start')<parseDate(first.end,'end');if(overlaps)conflicts.push({resourceId:first.resourceId,firstTaskId:first.id,secondTaskId:second.id});}}return conflicts;}
